// Local fixture adapter reproduces the IMAP resolved item and n8n binary storage.
// The webhook is local-only; it has no configurable destination URL or credentials.
const input = $input.first().json.body;
if (!input || !input.mail) throw new Error('INVALID_PAYLOAD: expected mail and attachments');
const binary = {};
for (const [i, attachment] of (input.attachments || []).entries()) {
  binary['attachment_' + i] = await this.helpers.prepareBinaryData(
    Buffer.from(attachment.content_base64, 'base64'), attachment.filename, attachment.mime_type
  );
}
return [{json: input.mail, binary}];

// Runs once for all IMAP items. Binary bytes are resolved through n8n's storage helper.
const output = [];
const items = $input.all();
function addresses(value) {
  const values = Array.isArray(value) ? value.flatMap(v => v.value ?? [v]) : (value?.value ?? []);
  return values.map(v => ({address: v.address, name: v.name || null}));
}
for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const mail = item.json;
  const senders = addresses(mail.from);
  if (senders.length !== 1) throw new Error('INVALID_PAYLOAD: exactly one parsed sender is required');
  const attachments = [];
  for (const [key, binary] of Object.entries(item.binary ?? {})) {
    const buffer = await this.helpers.getBinaryDataBuffer(index, key);
    attachments.push({filename: binary.fileName || key, mime_type: binary.mimeType || 'application/octet-stream', content_base64: buffer.toString('base64')});
  }
  output.push({json: {
    source_type: 'imap', external_message_id: mail.messageId || null,
    sender: senders[0], recipients: addresses(mail.to), cc: addresses(mail.cc), reply_to: addresses(mail.replyTo),
    subject: mail.subject || '', received_at: mail.receivedAt || new Date().toISOString(),
    sent_at: mail.date ? new Date(mail.date).toISOString() : null,
    text_body: typeof mail.text === 'string' ? mail.text : '',
    html_body: typeof mail.html === 'string' ? mail.html : null, attachments,
  }, pairedItem: {item: index}});
}
return output;

return $input.all().map(item => {
  const response = item.json;
  const body = response.body ?? response;
  if (response.error) {
    const error = response.error;
    const message = String(error.message ?? error);
    const status = Number(error.httpCode ?? error.statusCode ?? error.status ?? 0);
    let category = 'UNEXPECTED_WORKFLOW_ERROR';
    if (/timed?\s*out|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED|timeout/i.test(message)) category = 'BACKEND_TIMEOUT';
    else if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|service refused|connection.*(refused|closed)|not.*reachable/i.test(message)) category = 'BACKEND_UNAVAILABLE';
    else if ((status >= 400 && status < 500) || /\b(400|413|415|422)\b|invalid.*payload|could not be processed/i.test(message)) category = 'INVALID_PAYLOAD';
    else if (status >= 500) category = 'BACKEND_UNAVAILABLE';
    throw new Error(category + ': bounded delivery attempts exhausted; inspect execution and replay after fixing the cause');
  }
  if (!['created', 'duplicate'].includes(body.result) || !body.case_id || !body.message_id) {
    throw new Error('UNEXPECTED_WORKFLOW_ERROR: unrecognized backend response');
  }
  if (body.processing_status === 'failed' || body.status === 'FAILED') {
    throw new Error('INGESTION_FAILED: backend preserved a failed case ' + body.case_id + '; inspect it, do not create another message identity');
  }
  return {json: {...body, delivery_outcome: body.result === 'duplicate' ? 'idempotent_noop' : body.status === 'REVIEW_REQUIRED' ? 'operator_review' : 'accepted'}};
});
